#!/usr/bin/env python3
"""Generate src/cp949_table.c from Python's built-in cp949 codec.

Table layout: cp949_table[lead - 0x81][trail - 0x41] = Unicode code point (0 = invalid).
"""
import sys

out = sys.argv[1] if len(sys.argv) > 1 else "src/cp949_table.c"
lines = [
    "/* Generated by tools/gen_cp949_table.py -- do not edit. */",
    "#include <stdint.h>",
    "",
    "const uint16_t cp949_table[0xfe - 0x81 + 1][0xfe - 0x41 + 1] = {",
]
for lead in range(0x81, 0xFF):
    row = []
    for trail in range(0x41, 0xFF):
        try:
            ch = bytes([lead, trail]).decode("cp949")
            cp = ord(ch) if len(ch) == 1 and ord(ch) <= 0xFFFF else 0
        except UnicodeDecodeError:
            cp = 0
        row.append(cp)
    body = ",".join("0x%04x" % c for c in row)
    lines.append("\t{" + body + "},")
lines.append("};")
open(out, "w").write("\n".join(lines) + "\n")
